def fizzbuzz_value(n):
    """
    Повертає 'FizzBuzz', якщо n ділиться на 15, 'Fizz', якщо n ділиться на 3, 'Buzz', якщо n ділиться на 5, інакше повертає рядкове представлення n.
    """
    if n % 15 == 0:
        return 'FizzBuzz'
    elif n % 3 == 0:
        return 'Fizz'
    elif n % 5 == 0:
        return 'Buzz'
    else:
        return str(n)
```

